package main

import (
	"errors"
	"strings"
	"time"

	"github.com/robertkrimen/otto"
)

// Default timeout for script execution
const defaultScriptTimeout = 100 * time.Millisecond

// ErrScriptTimeout is returned when a script execution exceeds the allowed time limit
var ErrScriptTimeout = errors.New("script execution timed out")

// ErrEmptyScript is returned when an empty script is provided
var ErrEmptyScript = errors.New("condition script cannot be empty")

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	return FilterItemsWithTimeout(conditionScript, items, defaultScriptTimeout)
}

// FilterItemsWithTimeout is like FilterItems but allows specifying a custom timeout for script execution.
func FilterItemsWithTimeout(conditionScript string, items []map[string]interface{}, timeout time.Duration) ([]map[string]interface{}, error) {
	// Validate the script
	conditionScript = strings.TrimSpace(conditionScript)
	if conditionScript == "" {
		return nil, ErrEmptyScript
	}

	// Handle nil or empty items slice
	if len(items) == 0 {
		return []map[string]interface{}{}, nil
	}

	var result []map[string]interface{}

	for _, item := range items {
		match, err := evaluateCondition(conditionScript, item, timeout)
		if err != nil {
			return nil, err
		}

		if match {
			result = append(result, item)
		}
	}

	if result == nil {
		result = []map[string]interface{}{}
	}

	return result, nil
}

// evaluateCondition runs the JavaScript condition script for a single item with timeout protection.
func evaluateCondition(conditionScript string, item map[string]interface{}, timeout time.Duration) (bool, error) {
	vm := otto.New()

	// Set up interrupt handling for timeout
	vm.Interrupt = make(chan func(), 1)

	// Channel to receive the result
	type evalResult struct {
		match bool
		err   error
	}
	resultChan := make(chan evalResult, 1)

	// Run script in a goroutine
	go func() {
		defer func() {
			if r := recover(); r != nil {
				// Handle panic from vm.Interrupt (otto raises a panic when interrupted)
				resultChan <- evalResult{false, ErrScriptTimeout}
			}
		}()

		// Inject the current item as a global variable named 'item'
		err := vm.Set("item", item)
		if err != nil {
			resultChan <- evalResult{false, err}
			return
		}

		// Run the condition script
		value, err := vm.Run(conditionScript)
		if err != nil {
			resultChan <- evalResult{false, err}
			return
		}

		// Convert result to boolean using JavaScript truthiness
		boolResult, err := value.ToBoolean()
		if err != nil {
			resultChan <- evalResult{false, err}
			return
		}

		resultChan <- evalResult{boolResult, nil}
	}()

	// Wait for result or timeout
	select {
	case res := <-resultChan:
		return res.match, res.err
	case <-time.After(timeout):
		// Send interrupt signal to the VM
		vm.Interrupt <- func() {
			panic("Interrupt")
		}
		// Wait briefly for the goroutine to handle the interrupt
		select {
		case <-resultChan:
			// Goroutine handled the interrupt
		case <-time.After(50 * time.Millisecond):
			// Goroutine didn't respond in time, but we still return timeout error
		}
		return false, ErrScriptTimeout
	}
}

func main() {
	// Example usage
	items := []map[string]interface{}{
		{"id": 1, "active": true},
		{"id": 2, "active": false},
		{"id": 3, "active": true},
	}

	result, err := FilterItems("item.active == true", items)
	if err != nil {
		panic(err)
	}

	_ = result // Use result as needed
}

