		return nil, ErrNilItems
	}

	conditionScript = strings.TrimSpace(conditionScript)
	if conditionScript == "" {
		return nil, ErrEmptyScript
	}

	// Handle empty items slice
	if len(items) == 0 {
		return []map[string]interface{}{}, nil
	}

	var result []map[string]interface{}

	// Create a single VM instance and reuse it for better performance
	vm := otto.New()

	// Compile the script once for reuse
	script, err := vm.Compile("", conditionScript)
	if err != nil {
		return nil, err
	}

	for _, item := range items {
		boolResult, err := executeWithTimeout(vm, script, item, timeout)
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	if result == nil {
		result = []map[string]interface{}{}
	}

	return result, nil
}

// executeWithTimeout runs the script with a timeout to prevent infinite loops
func executeWithTimeout(vm *otto.Otto, script *otto.Script, item map[string]interface{}, timeout time.Duration) (bool, error) {
	// Create channels for result communication
	resultChan := make(chan bool, 1)
	errChan := make(chan error, 1)

	// Set up interrupt handling for timeout
	vm.Interrupt = make(chan func(), 1)

	go func() {
		defer func() {
			if r := recover(); r != nil {
				// Handle panic from vm.Interrupt
				if r == "halt" {
