const (
	// Maximum allowed script length to prevent overly complex scripts
	maxScriptLength = 4096
	// Execution timeout for each script evaluation
	executionTimeout = 100 * time.Millisecond
)

var (
	ErrEmptyScript      = errors.New("condition script cannot be empty")
	ErrScriptTooLong    = errors.New("condition script exceeds maximum allowed length")
	ErrExecutionTimeout = errors.New("script execution timed out")
	ErrNilItems         = errors.New("items slice cannot be nil")
)

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	// Validate inputs
	if err := validateInputs(conditionScript, items); err != nil {
		return nil, err
	}

	// Handle empty items slice
	if len(items) == 0 {
		return []map[string]interface{}{}, nil
	}

	var result []map[string]interface{}

	// Create a single VM instance for reuse
	vm := otto.New()

	// Disable potentially dangerous functions
	if err := sandboxVM(vm); err != nil {
		return nil, err
	}

	for _, item := range items {
