		if item == nil {
			continue
		}

		boolResult, err := evaluateWithTimeout(vm, conditionScript, item)
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	if result == nil {
		result = []map[string]interface{}{}
	}

	return result, nil
}

// validateInputs checks that the script and items are valid
func validateInputs(conditionScript string, items []map[string]interface{}) error {
	trimmedScript := strings.TrimSpace(conditionScript)
	if trimmedScript == "" {
		return ErrEmptyScript
	}

	if len(conditionScript) > maxScriptLength {
		return ErrScriptTooLong
	}

	if items == nil {
		return ErrNilItems
	}

	return nil
}

// sandboxVM disables potentially dangerous JavaScript functions
func sandboxVM(vm *otto.Otto) error {
	// Disable eval to prevent dynamic code execution within scripts
	if err := vm.Set("eval", nil); err != nil {
		return err
	}

	// Disable Function constructor to prevent creating new functions dynamically
	_, err := vm.Run(`Function = undefined;`)
	if err != nil {
		return err
	}

	return nil
}

// evaluateWithTimeout runs the script with a timeout to prevent infinite loops
func evaluateWithTimeout(vm *otto.Otto, conditionScript string, item map[string]interface{}) (bool, error) {
	// Set up interrupt channel
	done := make(chan struct{})
	errChan := make(chan error, 1)
	resultChan := make(chan bool, 1)

	// Set up the interrupt after timeout
	go func() {
		select {
		case <-time.After(executionTimeout):
			vm.Interrupt <- func() {
				panic(ErrExecutionTimeout)
			}
		case <-done:
			return
		}
	}()

