	go func() {
		defer func() {
			if r := recover(); r != nil {
				if err, ok := r.(error); ok {
					errChan <- err
				} else {
					errChan <- errors.New("script execution panicked")
				}
			}
		}()

		// Inject the current item as a global variable named 'item'
		err := vm.Set("item", item)
		if err != nil {
			errChan <- err
			return
		}

